krpano.action:
if(title !== null AND title != '',
	txtadd(txt_name, 'txt_', get(name));
	addhotspot(get(txt_name));
	hotspot[get(txt_name)].loadstyle(hs_title_box);
	set(hotspot[get(txt_name)].ath, get(ath));
	set(hotspot[get(txt_name)].atv, get(atv));
	set(hotspot[get(txt_name)].html, get(title));
	set(hotspot[get(txt_name)].linkedscene, get(linkedscene));
	set(hotspot[get(txt_name)].onclick,
		loadscene(get(linkedscene), null, MERGE, BLEND(0.7));
	);
);

if(layer[get(args[0])].visible,
	set(layer[get(args[0])].visible, false);
,
	hide_all_pc_sub();
	set(layer[get(args[0])].visible, true);
);

set(layer[pc_sub_1f].visible, false);
set(layer[pc_sub_2f].visible, false);
set(layer[pc_sub_3f].visible, false);

if(layer[mb_map_panel].visible,
	set(layer[mb_map_panel].visible, false);
,
	mb_close_all();
	set(layer[mb_map_panel].visible, true);
	update_mobile_minimap_location();
);

set(layer[mmap_1f_layer].visible, false);
set(layer[mmap_2f_layer].visible, false);
set(layer[mmap_3f_layer].visible, false);
if(args[0] == 1, set(layer[mmap_1f_layer].visible, true); );
if(args[0] == 2, set(layer[mmap_2f_layer].visible, true); );
if(args[0] == 3, set(layer[mmap_3f_layer].visible, true); );

txtadd(m_target_spot, 'm_spot_', get(xml.scene));
if(layer[get(m_target_spot)],
	set(layer[m_user_blue_circle].parent, get(layer[get(m_target_spot)].parent));
	set(layer[m_user_blue_circle].x, get(layer[get(m_target_spot)].x));
	set(layer[m_user_blue_circle].y, get(layer[get(m_target_spot)].y));
	set(layer[m_user_blue_circle].visible, true);
	set(m_parent_map, get(layer[get(m_target_spot)].parent));
	set(layer[mmap_1f_layer].visible, false);
	set(layer[mmap_2f_layer].visible, false);
	set(layer[mmap_3f_layer].visible, false);
	set(layer[get(m_parent_map)].visible, true);
,
	set(layer[m_user_blue_circle].visible, false);
);

set(layer[mb_menu_f1_panel].visible, false);
set(layer[mb_menu_f2_panel].visible, false);
set(layer[mb_menu_f3_panel].visible, false);
set(layer[mb_map_panel].visible, false);

set(layer[mb_btn_f1].html, "1층 ▲");
set(layer[mb_btn_f2].html, "2층 ▲");
set(layer[mb_btn_f3].html, "3층 ▲");

if(layer[mb_menu_f1_panel].visible,
    mb_close_all();
,
    mb_close_all();
    set(layer[mb_menu_f1_panel].visible, true);
    set(layer[mb_btn_f1].html, "1층 ▼");
);

if(layer[mb_menu_f2_panel].visible,
    mb_close_all();
,
    mb_close_all();
    set(layer[mb_menu_f2_panel].visible, true);
    set(layer[mb_btn_f2].html, "2층 ▼");
);

if(layer[mb_menu_f3_panel].visible,
    mb_close_all();
,
    mb_close_all();
    set(layer[mb_menu_f3_panel].visible, true);
    set(layer[mb_btn_f3].html, "3층 ▼");
);

set(layer[map_1f_layer].visible, false);
set(layer[map_2f_layer].visible, false);
set(layer[map_3f_layer].visible, false);

if(args[0] == 1, set(layer[map_1f_layer].visible, true); );
if(args[0] == 2, set(layer[map_2f_layer].visible, true); );
if(args[0] == 3, set(layer[map_3f_layer].visible, true); );

txtadd(target_spot, 'spot_', get(xml.scene));

if(layer[get(target_spot)],
	set(layer[user_blue_circle].parent, get(layer[get(target_spot)].parent));
	set(layer[user_blue_circle].x, get(layer[get(target_spot)].x));
	set(layer[user_blue_circle].y, get(layer[get(target_spot)].y));
	set(layer[user_blue_circle].visible, true);


	set(parent_map, get(layer[get(target_spot)].parent));
	set(layer[map_1f_layer].visible, false);
	set(layer[map_2f_layer].visible, false);
	set(layer[map_3f_layer].visible, false);
	set(layer[get(parent_map)].visible, true);
,
	set(layer[user_blue_circle].visible, false);
);
